import numpy as np
import os
import sys
import time

# Import lineage utilities
sys.path.append('storage/verity')
try:
    import lp_dual_grad as L
except Exception:
    # Minimal inline fallback if storage import fails unexpectedly
    class L:
        @staticmethod
        def clip_box(C, margin=1e-6):
            return np.clip(C, margin, 1.0 - margin)
        @staticmethod
        def boundary_margins(C):
            x, y = C[:,0], C[:,1]
            return np.minimum(np.minimum(x, 1-x), np.minimum(y, 1-y))
        @staticmethod
        def farthest_init(n, margin=0.01, candidates=400, seed=0):
            rng = np.random.default_rng(seed)
            C = [np.array([0.5,0.5])]
            for _ in range(1, n):
                cand = rng.uniform(margin, 1.0 - margin, size=(candidates, 2))
                exist = np.array(C)
                d2 = np.sum((cand[:,None,:]-exist[None,:,:])**2, axis=-1)
                d = np.sqrt(d2, out=np.zeros_like(d2), where=(d2>0))
                min_to_pts = np.min(d, axis=1)
                b = np.minimum(np.minimum(cand[:,0], 1-cand[:,0]), np.minimum(cand[:,1], 1-cand[:,1]))
                score = np.minimum(min_to_pts, 2.0*b)
                C.append(cand[int(np.argmax(score))])
            return L.clip_box(np.array(C, dtype=float))
        @staticmethod
        def safety_shrink(r):
            r2 = r.astype(float).copy()
            r2 *= 0.999
            return np.maximum(r2, 1e-12)
        @staticmethod
        def solve_lp(C):
            # Very conservative simple fallback without SciPy
            n = C.shape[0]
            b = L.boundary_margins(C)
            r = 0.5 * b
            # no pairwise adjustments here (safe shrink done later)
            return r, float(np.sum(r)), True, None, None, None, None
        @staticmethod
        def refine_centers(C0, time_budget=60.0, seed=0):
            # No-op refinement fallback
            r, obj, *_ = L.solve_lp(C0)
            return C0, r, obj

SAVE_PATH = 'storage/verity/sumr32_best.npz'

def _load_initial(n=32):
    # If a previous best exists, use it; otherwise farthest init
    if os.path.exists(SAVE_PATH):
        try:
            data = np.load(SAVE_PATH)
            C = data['centers'].astype(float)
            r = data['radii'].astype(float)
            if C.shape == (n, 2) and r.shape == (n,):
                return L.clip_box(C), r
        except Exception:
            pass
    return L.farthest_init(n, margin=0.01, candidates=500, seed=2025), None

def _save_best(C, r):
    try:
        obj = float(np.sum(r))
        os.makedirs(os.path.dirname(SAVE_PATH), exist_ok=True)
        np.savez(SAVE_PATH, centers=C, radii=r, obj=obj)
    except Exception:
        pass

def construct_packing() -> tuple:
    n = 32
    C0, r0 = _load_initial(n)
    # Time budget well within 1200s
    total_budget = 180.0
    Cb, Rb, Ob = L.refine_centers(C0, time_budget=total_budget, seed=12345)
    Rf = L.safety_shrink(Rb)

    # Ensure shapes and feasibility against box; LP guarantees non-overlap; shrink enforces strictness
    Cb = L.clip_box(Cb)
    if Cb.shape != (n, 2) or Rf.shape != (n,):
        # Fallback: trivial small equal radii grid (feasible)
        xs = np.linspace(1.0/(8+1), 1.0-1.0/(8+1), 8)
        ys = np.linspace(1.0/(4+1), 1.0-1.0/(4+1), 4)
        grid = np.array([(x, y) for y in ys for x in xs], dtype=float)[:n]
        b = np.minimum(np.minimum(grid[:,0], 1.0-grid[:,0]),
                       np.minimum(grid[:,1], 1.0-grid[:,1]))
        r = np.minimum(b, 0.03)
        return grid, r

    _save_best(Cb, Rf)
    return Cb, Rf
